def load() -> pd.DataFrame:
    import geopandas as gpd
    gdf = gpd.read_file('data/wildfire/input/usa.gpkg')
    gdf = gdf.copy()
    if 'geometry' in gdf.columns:
        gdf['geometry_wkt'] = gdf.geometry.to_wkt()
    return gdf.drop(columns=['geometry'], errors='ignore')

